def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _netuid_of(rec: Dict[str, Any]) -> Optional[int]:
    for key in ("netuid", "id", "subnet_id"):
        value = rec.get(key)
        if isinstance(value, int):
            return value
        if isinstance(value, str) and value.isdigit():
            return int(value)
    return None


