export type CommentLike = {
  id: number;
  body: string;
  createdAt: string;
  /** When the body was last edited. Absent when the source does not say. */
  updatedAt?: string;
  user: { login: string; type?: string } | null;
  performedViaGithubApp: { id?: number | null; slug?: string | null } | null;
