const VERDICT_LINE =
  /^(?:#{1,6}\s*)?(?:[*_\s]|\p{Extended_Pictographic}\uFE0F?)*(?:[A-Za-z][A-Za-z ]{0,24}:\s*)?[*_`]*(PASS|MODIFY|FAIL)[*_`]*(?![\w?])(.*)$/u;

