  /\bat\s+`?([0-9a-f]{40})(?![0-9a-f])/g,
  /[`'"]([0-9a-f]{12,40})[`'"]/g,
  /\b(?:head|sha|commit)\b[^\n]{0,3}?[`'"]?(?<![0-9a-f])([0-9a-f]{12,39})(?![0-9a-f])/g,
