        verdict,
        headSha: mcHead,
        sourceId: comment.id,
        at: lastSaid(comment),
        source: "comment",
      });
      continue;
    }

    const verdict = verdictFromComment(comment);
    if (verdict === undefined) {
      noteUnparsed(comment);
      continue;
    }
    let reviewer: ReviewerName | undefined;
    if (isDittoComment(comment)) {
      reviewer = "ditto";
    } else if (comment.user?.login === CURSOR_BOT_LOGIN) {
      reviewer = "cursor";
