        "validity": validity,
        "sources": list(sources or []),
        "disputed": disputed,
        "negative_since": negative_since,
        "refresh_incomplete": refresh_incomplete,
    }


def _merge_sources(
    prior: Optional[Dict[str, Any]],
    *,
