  let commentId: number | undefined;
  let superseded = false;
  const result = await ranOnce({
    kv,
    key,
    alreadyDone: () => alreadyPosted(octokit, ref, slot, headSha),
    run: async () => {
      commentId = await postComment(octokit, ref, `${marker(slot, headSha)}\n${body}`);
