  const posted = await postSlotOnce({
    octokit,
    kv,
    ref,
    headSha,
    slot: "cursor-ditto",
    key: cursorDittoTagKey(ref, headSha),
    body: cursorDittoTagBody(headSha),
  });
  return tagOutcome(posted, state.next);
