 * gate, so the caller's earlier state is not the authority.
 */
export async function tagReplit(input: {
  octokit: Octokit;
  kv: HostKvApi;
  ref: PrRef;
  headSha: string;
  /** The head the caller just read. A mismatch means a stale caller. */
  currentHeadSha: string;
