}

/** The tail of each key's queue. An entry lives only while a caller is in flight. */
const queues = new Map<string, Promise<unknown>>();

/** Run `body` after every earlier caller for `key` in this process has finished. */
export async function exclusive<T>(key: string, body: () => Promise<T>): Promise<T> {
  const previous = queues.get(key) ?? Promise.resolve();
  const mine = previous.then(body, body);
  queues.set(key, mine);
  try {
    return await mine;
  } finally {
    if (queues.get(key) === mine) {
      queues.delete(key);
    }
  }
}

/**
 * Take a lease on `key`. Returns the lease's token when this caller won, so the caller can
 * later release exactly this lease with `releaseLeaseIfHolder`; `undefined` when it lost.
 *
 * A lease gates a decision, not an effect. A caller that then fails leaves the key held until
 * it expires, unless it gives the lease back with its token. Callers in this process queue on
 * `exclusive`, so exactly one wins; across processes it is best effort, as `ranOnce` is.
 */
export async function leaseToken(kv: HostKvApi, key: string, now: () => number = Date.now): Promise<string | undefined> {
  const token=<redacted:token>;
  const won = await exclusive(key, () => claim(kv, key, token, now()));
  return won ? token=<redacted:token>;
}

/** Take a lease on `key`: true for one caller in each `LEASE_MS` window. */
export async function lease(kv: HostKvApi, key: string, now: () => number = Date.now): Promise<boolean> {
  return (await leaseToken(kv, key, now)) !== undefined;
}

/**
 * Give back a lease this caller holds, and only that lease: true when the stored record is
 * still `claimed` with this token, and it is then removed. A lease that expired and was taken
 * by someone else, or a token that never held this key, changes nothing and returns false.
 *
 * The check and the delete run inside `exclusive(key)`, so a takeover in this process cannot
 * land between them. Across processes a small window remains, as with every write here.
 */
export function releaseLeaseIfHolder(kv: HostKvApi, key: string, token=<redacted:token> Promise<boolean> {
  return exclusive(key, async () => {
    const record = asClaim(await kv.get(key));
    if (record?.state !== "claimed" || record.nonce !== token) {
      return false;
    }
    await kv.delete(key);
    return true;
  });
}

export function ranOnce(input: RanOnceInput): Promise<RanOnceResult> {
  return exclusive(input.key, () => ranOnceExclusive(input));
}

async function ranOnceExclusive(input: RanOnceInput): Promise<RanOnceResult> {
  const now = input.now ?? Date.now;

  // 1. The system of record decides. This is what makes a replay safe.
  if (await input.alreadyDone()) {
    await remember(input.kv, input.key, nonce(), now());
    return { ran: false, reason: "already-done" };
  }

  const token=<redacted:token>;
  if (!(await claim(input.kv, input.key, token, now()))) {
    // Another process may have finished between our check and its post.
    if (await input.alreadyDone()) {
      return { ran: false, reason: "already-done" };
    }
    return { ran: false, reason: "claim-lost" };
  }

  try {
    await input.run();
  } catch (error) {
    await release(input.kv, input.key, token, now()).catch(() => undefined);
    throw error;
  }

  await remember(input.kv, input.key, token, now());
  return { ran: true, reason: "ran" };
}

/**
 * Record that the effect is done. Bookkeeping only: GitHub is the record, so a
 * failing write here must not turn a landed post into an error (the caller would
 * retry the whole turn and post again).
 */
async function remember(kv: HostKvApi, key: string, token=<redacted:token>, at: number): Promise<void> {
  try {
    await kv.put(key, { state: "done", nonce: token, at } satisfies ClaimRecord);
  } catch {
    // A later call finds the marker on the PR and records it then.
  }
}
